fn conditional_average(
    vals_1: &Vec<u64>, 
    vals_2: &Vec<u64>, 
    conds_1: &Vec<bool>, 
    conds_2: &Vec<bool>, 
    avgs: &mut Vec<u64>
) {
    let n = vals_1.len();
    // Ensure all input vectors have the same length
    assert_eq!(vals_2.len(), n);
    assert_eq!(conds_1.len(), n);
    assert_eq!(conds_2.len(), n);

    // Clear and reserve space for output vector
    avgs.clear();
    avgs.reserve(n);

    for i in 0..n {
        debug_assert!(vals_1[i] < 1000);
        debug_assert!(vals_2[i] < 1000);
        debug_assert!(conds_1[i] || conds_2[i], "At least one condition must be true at index {}", i);

        let val = match (conds_1[i], conds_2[i]) {
            (true, true) => (vals_1[i] + vals_2[i]) / 2,
            (true, false) => vals_1[i],
            (false, true) => vals_2[i],
            (false, false) => unreachable!("Precondition violated: one boolean must be true"),
        };

        avgs.push(val);
    }
}